{
  "table": {
    "name": "legalities",
    "purpose": "One row per card printing per Magic: The Gathering format, stating whether that card is Legal, Banned or Restricted in that format. This is the standard MTGJSON-style legalities table accompanying the cards/sets/rulings tables: 55,608 distinct cards (uuid) x up to 15 formats = 427,907 rows."
  },
  "columns": {
    "format": {
      "role": "category",
      "name": "format",
      "description": "Magic: The Gathering tournament format in which the card's legality is recorded. The 15 distinct values are MTG format slugs: commander, legacy, vintage, duel (Duel Commander), modern, pioneer, pauper, penny (Penny Dreadful), premodern, etc. Eternal formats (commander/legacy/vintage, ~55,576 rows each) have an entry for essentially every card, while narrower formats like modern (40,774) only cover cards relevant to them.",
      "status": "resolved"
    },
    "id": {
      "role": "identifier",
      "name": "id",
      "description": "Synthetic auto-increment surrogate key (primary key) for the legality row. Values run 1–427,907 with a perfectly uniform distribution (min 1, max 427,907, mean = median), i.e. it is just a row number and carries no business meaning. The accepted joins to cards.mcmId, cards.mcmMetaId, cards.cardKingdomId, cards.cardKingdomFoilId and cards.tcgplayerProductId are coincidental numeric matches against a dense integer range, not real relationships.",
      "status": "resolved"
    },
    "status": {
      "role": "category",
      "name": "status",
      "description": "Legality of the card in the row's format: 'Legal' (playable, normal 4-copy limit; 424,958 rows), 'Banned' (not playable in that format; 2,313 rows), 'Restricted' (playable but limited to a single copy — a rule Magic: The Gathering uses in Vintage; 636 rows, a high count because each restricted card has many printings, each with its own uuid/row).",
      "status": "resolved"
    },
    "uuid": {
      "role": "foreign_key",
      "name": "uuid",
      "description": "Foreign key to cards.uuid: the unique identifier (MTGJSON-style v5 UUID) of the card printing whose legality this row records. Each uuid appears up to 15 times, once per format (55,608 distinct cards across 427,907 card–format rows), confirming the many-to-one relationship to the cards table.",
      "status": "resolved"
    }
  }
}
